延续刚才讨论的 **指针引用 `Node*&**` 机制以及现代 C++ 面向对象封装风格，实现完整的 AVL 树（包含四种旋转、插入、删除、查找、中序遍历）。

因为使用了 `Node*&`，在旋转和重新平衡时，**父指针会被自动更新绑定**，逻辑极为清爽。

```cpp
#include <iostream>
#include <algorithm>

class AVLTree {
private:
    struct Node {
        int val;
        int height;
        Node* left;
        Node* right;
        Node(int v) : val(v), height(1), left(nullptr), right(nullptr) {}
    };

    Node* root = nullptr;

    // 获取节点高度（空节点高度为 0）
    int getHeight(Node* node) const {
        return node ? node->height : 0;
    }

    // 更新节点高度
    void updateHeight(Node* node) {
        if (node) {
            node->height = 1 + std::max(getHeight(node->left), getHeight(node->right));
        }
    }

    // 计算平衡因子：左子树高度 - 右子树高度
    int getBalanceFactor(Node* node) const {
        return node ? getHeight(node->left) - getHeight(node->right) : 0;
    }

    // 右旋（LL 型失衡）
    // 注意：node 是引用，修改 node 会直接更新父节点对其的指向
    void rotateRight(Node*& node) {
        Node* lson = node->left;
        node->left = lson->right;
        lson->right = node;

        // 旋转后先更新原根节点高度，再更新新根节点高度
        updateHeight(node);
        updateHeight(lson);

        node = lson; // 关键：直接将父节点指向原左孩子
    }

    // 左旋（RR 型失衡）
    void rotateLeft(Node*& node) {
        Node* rson = node->right;
        node->right = rson->left;
        rson->left = node;

        updateHeight(node);
        updateHeight(rson);

        node = rson; // 关键：直接将父节点指向原右孩子
    }

    // 重新平衡当前子树
    void rebalance(Node*& node) {
        if (!node) return;

        updateHeight(node);
        int bf = getBalanceFactor(node);

        // LL 型：左子树过高且插入在左孩子的左边
        if (bf > 1 && getBalanceFactor(node->left) >= 0) {
            rotateRight(node);
        }
        // LR 型：左子树过高且插入在左孩子的右边
        else if (bf > 1 && getBalanceFactor(node->left) < 0) {
            rotateLeft(node->left);
            rotateRight(node);
        }
        // RR 型：右子树过高且插入在右孩子的右边
        else if (bf < -1 && getBalanceFactor(node->right) <= 0) {
            rotateLeft(node);
        }
        // RL 型：右子树过高且插入在右孩子的左边
        else if (bf < -1 && getBalanceFactor(node->right) > 0) {
            rotateRight(node->right);
            rotateLeft(node);
        }
    }

    // 递归插入（Node*& 自动处理挂载与回溯平衡）
    void push(int v, Node*& node) {
        if (!node) {
            node = new Node(v);
            return;
        }

        if (v < node->val) {
            push(v, node->left);
        } else if (v > node->val) {
            push(v, node->right);
        } else {
            return; // 树中已有相同值，不重复插入
        }

        // 递归回溯时逐层更新高度并平衡
        rebalance(node);
    }

    // 递归删除
    bool pop(int v, Node*& node) {
        if (!node) return false;

        bool removed = false;
        if (v < node->val) {
            removed = pop(v, node->left);
        } else if (v > node->val) {
            removed = pop(v, node->right);
        } else {
            // 找到了要删除的节点
            removed = true;
            if (!node->left || !node->right) {
                // 只有单侧孩子或为叶子节点
                Node* temp = node;
                node = node->left ? node->left : node->right;
                delete temp;
            } else {
                // 左右孩子都存在：找右子树最小值（中序后继）
                Node* succ = node->right;
                while (succ->left) succ = succ->left;
                node->val = succ->val;
                pop(succ->val, node->right); // 在右子树递归删除后继节点
            }
        }

        // 删除节点后，如果当前节点非空，回溯检验平衡
        if (node) {
            rebalance(node);
        }
        return removed;
    }

    // 中序遍历辅助
    void inorder(Node* node) const {
        if (!node) return;
        inorder(node->left);
        std::cout << node->val << " ";
        inorder(node->right);
    }

    // 析构清理内存
    void clear(Node* node) {
        if (!node) return;
        clear(node->left);
        clear(node->right);
        delete node;
    }

public:
    AVLTree() = default;

    ~AVLTree() {
        clear(root);
    }

    // 插入接口
    void push(int v) {
        push(v, root);
    }

    // 删除接口
    bool pop(int v) {
        return pop(v, root);
    }

    // 查找接口（沿用迭代写法）
    bool find(int v) const {
        Node* t = root;
        while (t && t->val != v) {
            if (v < t->val) t = t->left;
            else t = t->right;
        }
        return t != nullptr;
    }

    // 打印有序序列
    void print() const {
        inorder(root);
        std::cout << "\n";
    }

    // 获取根节点平衡因子（用于验证）
    int rootBalance() const {
        return getBalanceFactor(root);
    }
};

int main() {
    AVLTree avl;

    // 依次插入导致失衡的数据，触发多次自平衡旋转
    int data[] = {10, 20, 30, 40, 50, 25};
    for (int x : data) {
        avl.push(x);
    }

    std::cout << "中序遍历结果（升序）: ";
    avl.print(); // 输出应为有序: 10 20 25 30 40 50

    // 删除测试
    std::cout << "删除 40...\n";
    avl.pop(40);
    avl.print();

    std::cout << "查询 25 是否存在: " << (avl.find(25) ? "是" : "否") << "\n";
    std::cout << "查询 40 是否存在: " << (avl.find(40) ? "是" : "否") << "\n";

    return 0;
}

```

---

### 为什么用 `Node*&` 写 AVL 最舒服？

1. **无需返回值重赋**：传统写法每个旋转都要 `return newRoot`，然后在上一层写 `node->left = rotateLeft(...)`。而使用 `rotateRight(Node*& node)` 时，`node = lson` **会直接物理篡改父节点指向当前子树的那个指针**，不需要手动回传赋值。
2. **回溯天然更新**：`push` 和 `pop` 递归返回时，会自底向上执行 `rebalance(node)`，保证从受影响的叶子节点一直到根节点，沿途每个祖先节点的高度与平衡因子都被自动修复。

\cellbreak=[
]

不使用指针引用（即采用纯指针值传递 `Node*`）时，核心改动在于：**每个可能改变子树结构的函数（旋转、平衡、插入、删除）都必须返回当前子树调整后的新根节点指针**，并在上一层通过赋值（`node->left = ...`、`node->right = ...`）来完成指针重定向。

以下为纯指针值传递风格的完整 AVL 树实现：

```cpp
#include <iostream>
#include <algorithm>

class AVLTree {
private:
    struct Node {
        int val;
        int height;
        Node* left;
        Node* right;
        Node(int v) : val(v), height(1), left(nullptr), right(nullptr) {}
    };

    Node* root = nullptr;

    int getHeight(Node* node) const {
        return node ? node->height : 0;
    }

    void updateHeight(Node* node) {
        if (node) {
            node->height = 1 + std::max(getHeight(node->left), getHeight(node->right));
        }
    }

    int getBalanceFactor(Node* node) const {
        return node ? getHeight(node->left) - getHeight(node->right) : 0;
    }

    // 右旋：返回旋转后的新根节点
    Node* rotateRight(Node* y) {
        Node* x = y->left;
        Node* T2 = x->right;

        // 执行旋转
        x->right = y;
        y->left = T2;

        // 更新高度（先下后上）
        updateHeight(y);
        updateHeight(x);

        return x; // 返回新的子树根
    }

    // 左旋：返回旋转后的新根节点
    Node* rotateLeft(Node* x) {
        Node* y = x->right;
        Node* T2 = y->left;

        // 执行旋转
        y->left = x;
        x->right = T2;

        // 更新高度（先下后上）
        updateHeight(x);
        updateHeight(y);

        return y; // 返回新的子树根
    }

    // 重新平衡当前子树，并返回平衡后的根节点
    Node* rebalance(Node* node) {
        if (!node) return nullptr;

        updateHeight(node);
        int bf = getBalanceFactor(node);

        // LL 型
        if (bf > 1 && getBalanceFactor(node->left) >= 0) {
            return rotateRight(node);
        }
        // LR 型
        if (bf > 1 && getBalanceFactor(node->left) < 0) {
            node->left = rotateLeft(node->left);
            return rotateRight(node);
        }
        // RR 型
        if (bf < -1 && getBalanceFactor(node->right) <= 0) {
            return rotateLeft(node);
        }
        // RL 型
        if (bf < -1 && getBalanceFactor(node->right) > 0) {
            node->right = rotateRight(node->right);
            return rotateLeft(node);
        }

        return node;
    }

    // 插入：通过返回值接管更新后的子树指针
    Node* push(int v, Node* node) {
        if (!node) {
            return new Node(v);
        }

        if (v < node->val) {
            node->left = push(v, node->left);
        } else if (v > node->val) {
            node->right = push(v, node->right);
        } else {
            return node; // 存在相同元素直接原样返回
        }

        return rebalance(node);
    }

    // 删除：通过返回值接管更新后的子树指针
    Node* pop(int v, Node* node) {
        if (!node) return nullptr;

        if (v < node->val) {
            node->left = pop(v, node->left);
        } else if (v > node->val) {
            node->right = pop(v, node->right);
        } else {
            // 找到了待删除节点
            if (!node->left || !node->right) {
                // 只有单侧孩子或为叶子节点
                Node* temp = node->left ? node->left : node->right;
                if (!temp) {
                    // 叶子节点：直接释放当前节点，返回空
                    delete node;
                    return nullptr;
                } else {
                    // 单侧孩子：释放当前节点，返回其孩子接替位置
                    delete node;
                    return temp;
                }
            } else {
                // 左右孩子都存在：找右子树最小值（中序后继）
                Node* succ = node->right;
                while (succ->left) succ = succ->left;
                node->val = succ->val;
                // 递归删除右子树中的后继节点，并重新挂载右指针
                node->right = pop(succ->val, node->right);
            }
        }

        return rebalance(node);
    }

    void inorder(Node* node) const {
        if (!node) return;
        inorder(node->left);
        std::cout << node->val << " ";
        inorder(node->right);
    }

    void clear(Node* node) {
        if (!node) return;
        clear(node->left);
        clear(node->right);
        delete node;
    }

public:
    AVLTree() = default;

    ~AVLTree() {
        clear(root);
    }

    void push(int v) {
        root = push(v, root); // 外部接管新根
    }

    void pop(int v) {
        root = pop(v, root);  // 外部接管新根
    }

    bool find(int v) const {
        Node* t = root;
        while (t && t->val != v) {
            if (v < t->val) t = t->left;
            else t = t->right;
        }
        return t != nullptr;
    }

    void print() const {
        inorder(root);
        std::cout << "\n";
    }
};

int main() {
    AVLTree avl;

    int data[] = {10, 20, 30, 40, 50, 25};
    for (int x : data) {
        avl.push(x);
    }

    std::cout << "中序遍历结果: ";
    avl.print(); // 10 20 25 30 40 50

    avl.pop(40);
    std::cout << "删除 40 后: ";
    avl.print();

    std::cout << "查询 25: " << (avl.find(25) ? "存在" : "不存在") << "\n";
    std::cout << "查询 40: " << (avl.find(40) ? "存在" : "不存在") << "\n";

    return 0;
}

```

---

### 两种写法的关键差异

| 特征 | 指针引用法 (`Node*&`) | 函数返回值法 (`Node*`) |
| --- | --- | --- |
| **旋转函数原型** | `void rotateRight(Node*& node)` | `Node* rotateRight(Node* node)` |
| **挂载方式** | 直接在底层修改别名指针，自动就地挂载 | 显式使用 `node->left = push(...)` 或 `root = push(...)` |
| **平衡函数调用** | 直接传 `node` 执行，无返回值 | 必须写 `return rebalance(node)` 将新根往上传 |
| **语言兼容性** | 仅适用于 C++ | C 和 C++ 均可使用（纯 C 语言的标准写法） |

