## 2. 数据库操作

### 2.1 database/sql（标准库）

```go

import _ "github.com/lib/pq" // PostgreSQL 驱动

db, err := sql.Open("postgres", "postgres://user:pass@localhost/db?sslmode=disable")
if err != nil {
    log.Fatal(err)
}
defer db.Close()

// 配置连接池
db.SetMaxOpenConns(25)
db.SetMaxIdleConns(5)
db.SetConnMaxLifetime(5 * time.Minute)

// 查询单行
var name string
err := db.QueryRow("SELECT name FROM users WHERE id = $1", 1).Scan(&name)

// 查询多行
rows, err := db.Query("SELECT id, name FROM users WHERE age > $1", 18)
defer rows.Close()
for rows.Next() {
    var id int
    var name string
    rows.Scan(&id, &name)
}

// 执行写操作
result, err := db.Exec("INSERT INTO users (name, email) VALUES ($1, $2)",
    "Alice", "alice@example.com")
lastID, _ := result.LastInsertId()
affected, _ := result.RowsAffected()

// 事务
tx, err := db.Begin()
if err != nil {
    log.Fatal(err)
}
defer tx.Rollback() // 如果 Commit 没执行，则回滚

_, err = tx.Exec("UPDATE accounts SET balance = balance - $1 WHERE id = $2", 100, 1)
if err != nil {
    return err
}
_, err = tx.Exec("UPDATE accounts SET balance = balance + $1 WHERE id = $2", 100, 2)
if err != nil {
    return err
}
return tx.Commit()
```

